import { readFile, writeFile } from 'node:fs/promises';
import { emitOwnedAssets, verifyAssetInventory, renderHost, hostSource, productionOutput } from './asset-manifest.mjs';
import { buildCardRuntimeAssets } from './build-card-runtime.mjs';
const root = new URL('../', import.meta.url);
const runtime = await buildCardRuntimeAssets();
await emitOwnedAssets();
const output = renderHost(await readFile(new URL(hostSource, root), 'utf8'));
await writeFile(new URL(productionOutput, root), output);
await verifyAssetInventory();
console.log(JSON.stringify({output: productionOutput, source: hostSource, bytes: Buffer.byteLength(output), historicalTransformsExecuted: 0, cardRuntime: runtime}, null, 2));
